const fallbackPhotoByTrade:Record<Category,string>={Electrician:people[0].image,Plumber:people[1].image,Carpenter:people[2].image,Painter:people[3].image,Cleaner:people[4].image,Mason:people[5].image,'Solar tech':people[6].image,'Generator technician':people[6].image};
function mapProfessional(raw:ApiProfessional):Handyman{const p=people.find(person=>person.name===raw.userId?.fullName);const image=raw.userId?.profilePhotoUrl||fallbackPhotoByTrade[raw.serviceType as Category]||people[0].image;return{id:raw._id,name:raw.userId?.fullName||p?.name||'JobJoint professional',trade:(raw.serviceType||'Electrician') as Category,location:raw.location||p?.location||'Addis Ababa',rating:p?.rating||4.8,reviews:p?.reviews||0,jobs:p?.jobs||0,price:p?.price||700,years:raw.experienceYears||p?.years||0,image,cover:raw.portfolio?.[0]?.imageUrl||p?.cover||image,bio:raw.description||p?.bio||'',skills:p?.skills||[],phone:raw.userId?.phone||p?.phone||'',whatsapp:raw.contactLinks?.whatsapp||raw.userId?.socialLinks?.whatsapp||p?.whatsapp||'',certificate:raw.certificates?.[0]?`${raw.certificates[0].name} · ${raw.certificates[0].issuingOrganization}, ${raw.certificates[0].year}`:p?.certificate||'Verified JobJoint professional',award:raw.awards?.[0]?`${raw.awards[0].title} · ${raw.awards[0].issuer}, ${raw.awards[0].year}`:p?.award||'Local craft professional',work:raw.portfolio?.map(w=>({title:w.title,image:w.imageUrl}))||p?.work||[]};}
