function PortfolioManager({go}:{go:(p:string)=>void}){
 const [tab,setTab]=useState<'Work'|'Certificates'|'Awards'|'Photo'>('Work');
 const [work,setWork]=useState<SavedWork[]>(()=>{try{return JSON.parse(localStorage.getItem('jj-work')||'null')??people[0].work.map(w=>({title:w.title,description:'Completed with care for a local Addis family.',imageUrl:photo(w.image)}))}catch{return []}});
 const [certs,setCerts]=useState<SavedCredential[]>(()=>{try{return JSON.parse(localStorage.getItem('jj-certs')||'null')??[{title:'Certified Electrician',issuer:'Ethiopian TVET Agency',year:'2019'}]}catch{return []}});
 const [awards,setAwards]=useState<SavedCredential[]>(()=>{try{return JSON.parse(localStorage.getItem('jj-awards')||'null')??[{title:'Best Electrician',issuer:'Bole Sub-city Trade Fair',year:'2022'}]}catch{return []}});
 const [photoUrl,setPhotoUrl]=useState(()=>localStorage.getItem('jj-photo')||photo(people[0].image,300));const [photoData,setPhotoData]=useState('');
 useEffect(()=>{if(!localStorage.getItem('jj-access-token'))return;let active=true;apiFetch<{data:ApiProfessional}>('/api/handymen/me').then(({data})=>{if(!active)return;setWork((data.portfolio||[]).map(item=>({_id:item._id,title:item.title,description:item.description,imageUrl:item.imageUrl})));setCerts((data.certificates||[]).map(item=>({_id:item._id,title:item.name,issuer:item.issuingOrganization,year:item.year})));setAwards((data.awards||[]).map(item=>({_id:item._id,title:item.title,issuer:item.issuer,year:item.year})));if(data.userId?.profilePhotoUrl)setPhotoUrl(data.userId.profilePhotoUrl)}).catch(error=>{if(active)setNotice(error instanceof Error?error.message:'Could not load your saved profile.')});return()=>{active=false}},[]);
 const [title,setTitle]=useState(''),[issuer,setIssuer]=useState(''),[year,setYear]=useState('2025'),[imageUrl,setImageUrl]=useState(''),[description,setDescription]=useState(''),[notice,setNotice]=useState('');
 const save=async()=>{setNotice('');const connected=Boolean(localStorage.getItem('jj-access-token'));try{if(tab==='Work'){if(title.trim().length<3||description.trim().length<8||!imageUrl.startsWith('https://')){setNotice('Add a title, a short description, and a valid secure image URL.');return}const entry={title:title.trim(),description:description.trim(),imageUrl:imageUrl.trim(),completedDate:new Date().toISOString()};if(connected){const result=await apiFetch<{data:SavedWork}>('/api/handymen/me/portfolio',{method:'POST',body:JSON.stringify(entry)});setWork(current=>[result.data,...current])}else{const next=[{...entry},...work];setWork(next);localStorage.setItem('jj-work',JSON.stringify(next))}setTitle('');setDescription('');setImageUrl('')}else if(tab==='Certificates'||tab==='Awards'){if(title.trim().length<3||issuer.trim().length<2||!/^\d{4}$/.test(year)){setNotice('Add a title, an issuing organization and a four-digit year.');return}const value=tab==='Awards'?{title:title.trim(),issuer:issuer.trim(),year:Number(year)}:{name:title.trim(),issuingOrganization:issuer.trim(),year:Number(year)};if(connected){const result=await apiFetch<{data:{_id?:string;title?:string;name?:string;issuer?:string;issuingOrganization?:string;year:number}}>(`/api/handymen/me/${tab.toLowerCase()}`,{method:'POST',body:JSON.stringify(value)});const item:SavedCredential={_id:result.data._id,title:result.data.title||result.data.name||title.trim(),issuer:result.data.issuer||result.data.issuingOrganization||issuer.trim(),year:result.data.year};if(tab==='Awards')setAwards(current=>[item,...current]);else setCerts(current=>[item,...current])}else{const item={title:title.trim(),issuer:issuer.trim(),year};if(tab==='Awards'){const next=[item,...awards];setAwards(next);localStorage.setItem('jj-awards',JSON.stringify(next))}else{const next=[item,...certs];setCerts(next);localStorage.setItem('jj-certs',JSON.stringify(next))}}setTitle('');setIssuer('')}else{if(photoData){if(connected){const saved=await apiFetch<{data:{profilePhotoUrl:string}}>('/api/handymen/me/photo',{method:'POST',body:JSON.stringify({photoData})});setPhotoUrl(saved.data.profilePhotoUrl)}else localStorage.setItem('jj-photo',photoData);setPhotoData('')}else if(!photoUrl.startsWith('https://')){setNotice('Choose a photo or enter a secure image URL.');return}else if(connected){setNotice('Choose a photo file to upload.');return}else localStorage.setItem('jj-photo',photoUrl)}setNotice(connected?'Your changes are saved to your JobJoint profile.':'Changes saved in this browser demo.')}catch(error){setNotice(error instanceof Error?error.message:'Could not save your changes. Please try again.')}};
 const remove=async(kind:'work'|'certs'|'awards',index:number)=>{const list=kind==='work'?work:kind==='certs'?certs:awards;const item=list[index];if(localStorage.getItem('jj-access-token')&&item?._id){const route=kind==='work'?'portfolio':kind==='certs'?'certificates':'awards';try{await apiFetch(`/api/handymen/me/${route}/${item._id}`,{method:'DELETE'})}catch(error){setNotice(error instanceof Error?error.message:'Could not remove this item.');return}}if(kind==='work'){const next=work.filter((_,i)=>i!==index);setWork(next);if(!localStorage.getItem('jj-access-token'))localStorage.setItem('jj-work',JSON.stringify(next))}if(kind==='certs'){const next=certs.filter((_,i)=>i!==index);setCerts(next);if(!localStorage.getItem('jj-access-token'))localStorage.setItem('jj-certs',JSON.stringify(next))}if(kind==='awards'){const next=awards.filter((_,i)=>i!==index);setAwards(next);if(!localStorage.getItem('jj-access-token'))localStorage.setItem('jj-awards',JSON.stringify(next))}};
 return <main className="portfolio-manager"><div className="wrap"><div className="breadcrumb"><button onClick={()=>go('/')}>Home</button><span>/</span><button onClick={()=>go('/handyman/requests')}>Your workspace</button><span>/</span><span>Manage portfolio</span></div><div className="manager-heading"><div><div className="eyebrow"><span className="eyebrow-line"/> A LITTLE CARE GOES A LONG WAY</div><h1>Let your work <em>speak.</em></h1><p>Help your next neighbour see what you do best.</p></div><button className="text-link" onClick={()=>go('/handymen/dawit')}>Preview your profile <ArrowRight size={15}/></button></div><div className="dashboard-tabs manager-tabs">{(['Work','Certificates','Awards','Photo'] as const).map(t=><button className={tab===t?'selected':''} onClick={()=>{setTab(t);setNotice('')}} key={t}>{t}{t==='Work'?<span>{work.length}</span>:t==='Certificates'?<span>{certs.length}</span>:t==='Awards'?<span>{awards.length}</span>:null}</button>)}</div><div className="manager-layout"><section className="manager-list"><div className="dash-panel-heading"><div><span className="section-kicker"><span>WHAT NEIGHBOURS CAN SEE</span></span><h2>Your {tab.toLowerCase()}, <em>with care.</em></h2></div></div>{tab==='Work'&&<div className="manager-items">{work.map((item,i)=><article className="manager-item" key={`${item.title}-${i}`}><img src={item.imageUrl} alt={item.title}/><div><b>{item.title}</b><small>{item.description}</small></div><button className="remove-item" aria-label={`Remove ${item.title}`} onClick={()=>remove('work',i)}><X size={16}/></button></article>)}{work.length===0&&<p className="manager-empty">Add a couple of finished jobs to show your craft.</p>}</div>}{(tab==='Certificates'||tab==='Awards')&&<div className="manager-items">{(tab==='Awards'?awards:certs).map((item,i)=><article className="manager-credential" key={`${item.title}-${i}`}><span className="credential-icon">{tab==='Awards'?<Sparkles size={17}/>:<BadgeCheck size={17}/>}</span><div><b>{item.title}</b><small>{item.issuer} · {item.year}</small></div><button className="remove-item" aria-label={`Remove ${item.title}`} onClick={()=>remove(tab==='Awards'?'awards':'certs',i)}><X size={16}/></button></article>)}</div>}{tab==='Photo'&&<div className="photo-editor"><img src={photoUrl} alt="Your profile photo preview"/><p>Choose a clear photo of yourself. JPEG, PNG, or WebP, up to 2 MB.</p><label className="photo-file-label">Choose photo<input type="file" accept="image/jpeg,image/png,image/webp" onChange={event=>{const file=event.currentTarget.files?.[0];if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>2*1024*1024){setNotice("Choose a JPEG, PNG, or WebP image under 2 MB.");return}const reader=new FileReader();reader.onload=()=>{const value=String(reader.result||"");setPhotoData(value);setPhotoUrl(value);setNotice("")};reader.readAsDataURL(file)}}/></label></div>}</section><section className="manager-form"><span className="summary-label">ADD SOMETHING GOOD</span><h3>{tab==='Work'?'Show a finished job':tab==='Photo'?'Your profile photo':`Add a ${tab==='Awards'?'recognition':'qualification'}`}</h3><p>{tab==='Work'?'A real example helps neighbours picture your work.':tab==='Photo'?'A friendly, clear photo helps people know who they are inviting in.':'A little recognition can help your next customer feel confident.'}</p>{tab==='Work'&&<><label>Project title<input value={title} onChange={e=>setTitle(e.target.value)} placeholder="A brighter kitchen in Bole"/></label><label>Short description<textarea value={description} onChange={e=>setDescription(e.target.value)} placeholder="What did you do, and how did it help?" rows={3}/></label><label>Project image URL<input value={imageUrl} onChange={e=>setImageUrl(e.target.value)} placeholder="https://…"/></label></>}{(tab==='Awards'||tab==='Certificates')&&<><label>{tab==='Awards'?'Award or recognition':'Certificate name'}<input value={title} onChange={e=>setTitle(e.target.value)} placeholder={tab==='Awards'?'Best Plumber':'Certified Electrician'}/></label><label>Issuing organization<input value={issuer} onChange={e=>setIssuer(e.target.value)} placeholder="Ethiopian TVET Agency"/></label><label>Year earned<input inputMode="numeric" value={year} onChange={e=>setYear(e.target.value)} placeholder="2024"/></label></>}{notice&&<p className={notice.startsWith('Add')||notice.startsWith('Enter')?'form-error':'save-notice'} role="status">{notice}</p>}<button className="button full-button" onClick={save}>{tab==='Photo'?'Save photo':'Save changes'} <Check size={15}/></button><div className="manager-reminder"><ShieldCheck size={15}/> Only share work you completed and credentials you earned.</div></section></div><button className="text-link" onClick={()=>go('/handyman/requests')}><ArrowLeft size={15}/> Back to your workspace</button></div></main>
}
function AccountProfile({user,onUpdated,go}:{user:ApiUser|null;onUpdated:(user:ApiUser)=>void;go:(path:string)=>void}){
 const [photoUrl,setPhotoUrl]=useState(user?.profilePhotoUrl||'');const [photoData,setPhotoData]=useState('');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);
 const choose=(event:ChangeEvent<HTMLInputElement>)=>{const file=event.currentTarget.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024){setMessage('Choose a JPEG, PNG, or WebP image under 2 MB.');return}const reader=new FileReader();reader.onload=()=>{const value=String(reader.result||'');setPhotoData(value);setPhotoUrl(value);setMessage('')};reader.readAsDataURL(file)};
 const save=async()=>{if(!photoData){setMessage('Choose a photo from your device first.');return}setBusy(true);setMessage('');try{const result=await apiFetch<{data:{profilePhotoUrl:string}}>('/api/users/me/photo',{method:'POST',body:JSON.stringify({photoData})});const next={...user!,profilePhotoUrl:result.data.profilePhotoUrl};onUpdated(next);setPhotoUrl(result.data.profilePhotoUrl);setPhotoData('');setMessage('Your profile photo is saved.')}catch(error){setMessage(error instanceof Error?error.message:'Could not save your photo. Try again.')}finally{setBusy(false)}};
 if(!user)return <main className="account-page"><div className="wrap"><h1>Your profile</h1><p>Please sign in to view and edit your profile.</p><button className="button" onClick={()=>go('/')}>Go to JobJoint <ArrowRight size={16}/></button></div></main>;
 return <main className="account-page"><div className="wrap"><div className="breadcrumb"><button onClick={()=>go('/')}>Home</button><span>/</span><span>Your profile</span></div><div className="account-card"><div className="eyebrow"><span className="eyebrow-line"/> YOUR JOBJOINT PROFILE</div><h1>Your profile</h1><p>Signed in as <strong>{user.fullName}</strong>. {user.userType==='HANDYMAN'?'Professional account':'Customer account'}.</p><img className="account-photo-preview" src={photoUrl||`https://ui-avatars.com/api/?name=${encodeURIComponent(user.fullName)}&background=e7ede4&color=17634f&size=240`} alt="Profile photo preview"/><label className="account-upload">Select a photo<input type="file" accept="image/jpeg,image/png,image/webp" onChange={choose}/></label><span className="account-hint">JPEG, PNG, or WebP · maximum 2 MB</span>{message&&<p className={message.startsWith('Choose')?'form-error':'save-notice'} role="status">{message}</p>}<button className="button" onClick={()=>void save()} disabled={busy}>{busy?'Saving…':'Save profile photo'} <Check size={16}/></button><button className="text-link account-back" onClick={()=>go(user.userType==='HANDYMAN'?'/handyman/requests':'/my-requests')}>Back to my {user.userType==='HANDYMAN'?'workspace':'requests'} <ArrowRight size={15}/></button></div></div></main>
}function Modal({type,close,onLogin,onSignup,onGoogle}:{type:string;close:()=>void;onLogin:(email:string,password:string)=>Promise<void>;onSignup:(data:Parameters<typeof signupApi>[0])=>Promise<void>;onGoogle:(credential:string,intent:'login'|'signup',profile?:Parameters<typeof googleAuthApi>[2])=>Promise<void>}){const [email,setEmail]=useState(''),[name,setName]=useState(''),[password,setPassword]=useState(''),[phone,setPhone]=useState(''),[location,setLocation]=useState('Bole, Addis Ababa'),[description,setDescription]=useState(''),[serviceType,setServiceType]=useState<Category>('Electrician'),[userType,setUserType]=useState<'CUSTOMER'|'HANDYMAN'>('CUSTOMER'),[sent,setSent]=useState(false),[busy,setBusy]=useState(false),[stage,setStage]=useState<'accept'|'decline'|''>('');const [localError,setLocalError]=useState('');const [signup,setSignup]=useState(type==='signup');const googleButtonRef=useRef<HTMLDivElement>(null),googleClientId=import.meta.env.VITE_GOOGLE_CLIENT_ID||'';const decision=type==='decision';const result=type==='accepted'||type==='declined'?type:stage?stage==='accept'?'accepted':'declined':'';const beginGoogle=async(credential:string)=>{if(signup&&(!phone.trim()||phone.trim().length<7||(userType==='HANDYMAN'&&description.trim().length<12))){setLocalError(userType==='HANDYMAN'?'Enter your phone number and professional bio below before continuing with Google.':'Enter your phone number below before continuing with Google.');return}setBusy(true);setLocalError('');try{const profile=signup?{fullName:name.trim(),phone:phone.trim(),userType,location,...(userType==='HANDYMAN'?{serviceType,description:description.trim()}:{})}:undefined;await onGoogle(credential,signup?'signup':'login',profile);}catch(error){setLocalError(error instanceof Error?error.message:'Google sign-in could not be completed. Please try again.')}finally{setBusy(false)}};useEffect(()=>{if(!googleClientId||!googleButtonRef.current)return;let active=true;const render=()=>{if(!active||!window.google?.accounts.id||!googleButtonRef.current)return;const mount=googleButtonRef.current;mount.replaceChildren();window.google.accounts.id.initialize({client_id:googleClientId,callback:response=>void beginGoogle(response.credential)});window.google.accounts.id.renderButton(mount,{theme:'outline',size:'large',text:'continue_with',shape:'rectangular',width:Math.min(360,mount.clientWidth||360)});};if(window.google?.accounts.id)render();else{let script=document.querySelector<HTMLScriptElement>('script[data-google-identity]');if(!script){script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.defer=true;script.dataset.googleIdentity='true';document.head.appendChild(script)}script.addEventListener('load',render,{once:true});}return()=>{active=false}},[googleClientId,signup,name,phone,location,userType,serviceType,description,onGoogle]);const complete=async()=>{if(!email.includes('@')||(signup&&!name.trim())||password.length<8||(signup&&phone.trim().length<7)||(signup&&userType==='HANDYMAN'&&description.trim().length<12)){setLocalError(signup?'Add your name, a valid email, an 8-character password, phone number, and professional bio.':'Enter a valid email and password (at least 8 characters).');return}setBusy(true);setLocalError('');try{if(signup){await onSignup({fullName:name.trim(),email,password,phone:phone.trim(),userType,location,...(userType==='HANDYMAN'?{serviceType,description:description.trim(),experienceYears:0}:{})});setSent(true)}else await onLogin(email,password)}catch(error){setLocalError(error instanceof Error?error.message:'Could not connect to the JobJoint API. Check that the backend is running.')}finally{setBusy(false)}};return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="modal-card"><button className="modal-close" onClick={close} aria-label="Close"><X size={19}/></button><span className="modal-mark"><Wrench size={19}/></span>{decision?<><div className="eyebrow">A NEIGHBOUR NEEDS YOUR HELP</div><h2>Take on this <em>request?</em></h2><p>Accepting lets the customer know you’re available. You can discuss the details directly before agreeing on the work.</p><button className="button full-button" onClick={()=>setStage('accept')}>Accept request <Check size={15}/></button><button className="cancel-link" style={{display:'block',margin:'13px auto 0'}} onClick={()=>setStage('decline')}>Decline this request</button></>:result?<><div className="modal-success"><span><Check/></span><div className="eyebrow">{result==='accepted'?'REQUEST ACCEPTED':'REQUEST DECLINED'}</div><h2>{result==='accepted'?'Good things start':'Thanks for letting'}<br/><em>{result==='accepted'?'with a hello.':'them know.'}</em></h2><p>{result==='accepted'?'The customer can now contact you directly to agree on a time and the details.':'The customer will be notified and can find another professional nearby.'}</p></div><button className="button full-button" onClick={close}>Sounds good <ArrowRight size={15}/></button></>:sent?<><div className="modal-success"><span><Check/></span><div className="eyebrow">YOUR ACCOUNT IS READY</div><h2>Good to meet you,<br/><em>{name.split(' ')[0]}.</em></h2><p>Your JobJoint account is ready. Sign in any time to get back to your neighbourhood.</p></div><button className="button full-button" onClick={close}>Sounds good <ArrowRight size={15}/></button></>:<><div className="eyebrow">{signup?'GOOD WORK STARTS HERE':'WELCOME BACK'}</div><h2>{signup?'Join the good work.':'Good to see you.'}</h2><p>{signup?'Grow your work with neighbours who value what you do.':'Your neighbours and your next good job are right here.'}</p>{googleClientId&&<><div className="google-signin-mount" ref={googleButtonRef}/><div className="modal-divider"><span/>or with email<span/></div></>}{signup&&<><label>Your name<input value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Dawit Bekele"/></label><fieldset className="account-type-field"><legend>Choose your account type</legend><div className="account-type-options"><button type="button" className={userType==='CUSTOMER'?'account-type-option selected':'account-type-option'} aria-pressed={userType==='CUSTOMER'} onClick={()=>setUserType('CUSTOMER')}><strong>Customer</strong><span>Find and hire trusted local professionals.</span></button><button type="button" className={userType==='HANDYMAN'?'account-type-option selected':'account-type-option'} aria-pressed={userType==='HANDYMAN'} onClick={()=>setUserType('HANDYMAN')}><strong>Professional</strong><span>Offer your services and receive job requests.</span></button></div></fieldset><label>Phone number<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+251 91 234 5678"/></label><label>Neighbourhood<input value={location} onChange={e=>setLocation(e.target.value)} placeholder="Bole, Addis Ababa"/></label>{userType==='HANDYMAN'&&<><label>Your service<select value={serviceType} onChange={e=>setServiceType(e.target.value as Category)}>{trades.map(t=><option key={t}>{t}</option>)}</select></label><label>A little about your work<textarea rows={3} value={description} onChange={e=>setDescription(e.target.value)} placeholder="Tell neighbours about your experience and the work you do."/></label></>}</>}<label>Email address<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/></label>{localError&&<span className="form-error" role="alert">{localError}</span>}<button className="button full-button modal-submit" onClick={()=>void complete()} disabled={busy}>{busy?'Please wait…':signup?'Create my account':'Log in'} <ArrowRight size={15}/></button><small className="modal-switch">{signup?'Already with us?':'New to JobJoint?'} <button onClick={()=>{setLocalError('');setSent(false);setSignup(value=>!value)}}>{signup?'Log in':'Create an account'}</button></small><div className="modal-footnote"><ShieldCheck size={13}/> Your details stay safe and private.</div></>}</div></div>}

export default App;
